:root {
  --color-primary: #2d5a3d;
  --color-primary-dark: #1a3624;
  --color-accent: #d4a574;
  --color-accent-light: #f5e6d3;
  --color-accent-on-dark: #f5d9b8;
  --color-text: #2c2c2c;
  --color-text-light: #5a5a5a;
  --color-bg: #fafaf8;
  --color-border: #e8e6e1;
  --color-white: #ffffff;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --max-width: 1200px;
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3 {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  line-height: 1.2;
  margin-bottom: var(--spacing-md);
}

h1 {
  font-size: 2.5rem;
}

h2 {
  font-size: 2rem;
}

h3 {
  font-size: 1.5rem;
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
  transition: var(--transition);
}

a:hover {
  color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header */
.site-header {
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md);
}

.logo {
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: 1.8rem;
  font-weight: 400;
  color: var(--color-primary-dark);
  text-decoration: none;
  white-space: nowrap;
  text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.1);
  transition: var(--transition);
}

.logo:hover {
  color: var(--color-accent);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.site-header nav {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.site-header nav a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 500;
  transition: var(--transition);
}

.site-header nav a:hover {
  color: var(--color-primary-dark);
}

/* Footer */
.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  margin-top: var(--spacing-xl);
  padding: var(--spacing-xl) var(--spacing-md);
}

.site-footer .container {
  text-align: center;
}

.site-footer a {
  color: var(--color-accent-on-dark);
}

.site-footer a:hover {
  text-decoration: none;
  color: var(--color-white);
}

.site-footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.95rem;
}

/* Buttons */
button,
.btn {
  display: inline-block;
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border: none;
  padding: 0.875rem 1.75rem;
  border-radius: 4px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: var(--transition);
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

button:hover,
.btn:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
}

button:focus,
.btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

/* Forms */
form {
  max-width: 600px;
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

input,
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  margin-bottom: var(--spacing-md);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  transition: var(--transition);
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(45, 90, 61, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

/* Cards */
.card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
  transition: var(--transition);
}

.card:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
  transform: translateY(-4px);
}

.card-image {
  width: 100%;
  display: block;
  background-color: var(--color-accent-light);
}

.card-content {
  padding: var(--spacing-md);
}

.card-content h3 {
  margin-bottom: var(--spacing-sm);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

/* Sections */
section {
  padding: var(--spacing-xl) 0;
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

/* Mobile */
@media (max-width: 600px) {
  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  h3 {
    font-size: 1.25rem;
  }

  .site-header .container {
    flex-direction: column;
    gap: var(--spacing-md);
    padding: var(--spacing-md);
  }

  .logo {
    font-size: 1.5rem;
  }

  .site-header nav {
    width: 100%;
    justify-content: center;
    gap: var(--spacing-md);
  }

  .site-header nav a {
    font-size: 0.95rem;
  }

  .grid {
    gap: var(--spacing-md);
    grid-template-columns: 1fr;
  }

  .grid-2 {
    grid-template-columns: 1fr;
  }

  button,
  .btn {
    width: 100%;
  }

  section {
    padding: var(--spacing-lg) 0;
  }

  .container {
    padding: 0 var(--spacing-sm);
  }
}

/* Desktop */
@media (min-width: 601px) {
  .site-header nav {
    gap: var(--spacing-xl);
  }

  section {
    padding: var(--spacing-xl) 0;
  }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

pages.css:
.index-hero {
  text-align: center;
}

.index-hero h1 {
  color: var(--color-white) !important;
}

.index-hero .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.index-about-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: center;
}

.index-about-text {
  max-width: 500px;
}

.index-about-text h2 {
  color: var(--color-primary-dark);
}

.index-about-text p {
  color: var(--color-text);
  line-height: 1.8;
}

.index-about-stats {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.index-stat {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border-left: 4px solid var(--color-primary-dark);
  text-align: center;
}

.index-stat-number {
  font-family: var(--font-serif);
  font-size: 2.5rem;
  font-weight: bold;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-xs);
}

.index-stat-label {
  font-size: 0.95rem;
  color: var(--color-text-light);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.index-cta-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.index-cta-text {
  max-width: 500px;
}

.index-cta-text h3 {
  margin-bottom: var(--spacing-md);
}

.index-process-list {
  list-style: none;
  margin-bottom: var(--spacing-md);
}

.index-process-list li {
  padding: var(--spacing-sm) 0;
  padding-left: var(--spacing-lg);
  position: relative;
  color: var(--color-text);
}

.index-process-list li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-primary-dark);
  font-weight: bold;
}

.index-cta-box {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  padding: var(--spacing-lg);
  border-radius: 8px;
  text-align: center;
}

.index-cta-box h3 {
  color: var(--color-primary-dark);
}

.index-cta-box p {
  color: var(--color-text-light);
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) 0 !important;
  }

  .index-hero h1 {
    font-size: 2rem;
    margin-bottom: var(--spacing-sm);
  }

  .index-hero p {
    font-size: 1rem;
    margin-bottom: var(--spacing-md);
  }

  .index-about-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .index-about-stats {
    flex-direction: row;
    gap: var(--spacing-md);
  }

  .index-stat {
    flex: 1;
    padding: var(--spacing-md);
  }

  .index-stat-number {
    font-size: 1.75rem;
  }

  .index-stat-label {
    font-size: 0.8rem;
  }

  .index-cta-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .index-cta-text {
    max-width: 100%;
  }

  .index-cta-box {
    max-width: 100%;
  }
}

@media (min-width: 601px) {
  .index-about-content {
    grid-template-columns: 1fr 1fr;
  }

  .index-cta-content {
    grid-template-columns: 1fr 1fr;
  }
}

.work-hero {
  background-color: var(--color-white);
  padding: var(--spacing-xl) 0;
  border-bottom: 1px solid var(--color-border);
}

.work-hero h1 {
  margin-bottom: var(--spacing-md);
}

.work-intro {
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 600px;
}

.work-filters {
  padding: var(--spacing-lg) 0;
  background-color: var(--color-white);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 80px;
  z-index: 50;
}

.filter-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-md);
  justify-content: center;
}

.work-filter-btn {
  background-color: transparent;
  color: var(--color-text);
  border: 2px solid var(--color-border);
  padding: 0.625rem 1.25rem;
  border-radius: 24px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  min-height: auto;
  display: inline-block;
  text-decoration: none;
}

.work-filter-btn:hover {
  border-color: var(--color-primary-dark);
  color: var(--color-primary-dark);
  background-color: transparent;
}

.work-filter-btn--active {
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border-color: var(--color-primary-dark);
}

.work-filter-btn--active:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
  border-color: var(--color-accent);
}

.work-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--spacing-lg);
}

.work-item {
  display: flex;
  flex-direction: column;
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
  transition: var(--transition);
  cursor: pointer;
}

.work-item:hover {
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.12);
  transform: translateY(-6px);
}

.work-item figure {
  display: flex;
  flex-direction: column;
  height: 100%;
  margin: 0;
}

.work-item img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  display: block;
  background-color: var(--color-accent-light);
}

.work-item figcaption {
  padding: var(--spacing-md);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.work-item h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

.work-item p {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-md);
  flex-grow: 1;
}

.work-category {
  display: inline-block;
  background-color: var(--color-accent-light);
  color: var(--color-primary-dark);
  padding: 0.35rem 0.75rem;
  border-radius: 4px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.work-cta {
  text-align: center;
  padding: var(--spacing-xl) 0;
}

.work-cta h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.work-cta p {
  font-size: 1.05rem;
  color: var(--color-text);
  max-width: 600px;
  margin: 0 auto var(--spacing-lg);
}

@media (max-width: 600px) {
  .work-hero {
    padding: var(--spacing-lg) 0;
  }

  .work-intro {
    font-size: 1rem;
  }

  .work-filters {
    padding: var(--spacing-md) 0;
    top: 100%;
  }

  .filter-buttons {
    gap: var(--spacing-sm);
    justify-content: flex-start;
    overflow-x: auto;
    padding: 0 var(--spacing-sm);
  }

  .work-filter-btn {
    padding: 0.5rem 1rem;
    font-size: 0.9rem;
    flex-shrink: 0;
  }

  .work-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .work-item img {
    height: 240px;
  }

  .work-item h3 {
    font-size: 1.1rem;
  }

  .work-cta {
    padding: var(--spacing-lg) 0;
  }

  .work-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) and (max-width: 900px) {
  .work-grid {
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  }
}

@media (min-width: 901px) {
  .work-grid {
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  }
}

.commission-steps {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.commission-step {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  text-align: center;
  transition: var(--transition);
}

.commission-step:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
  transform: translateY(-4px);
}

.step-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  border-radius: 50%;
  font-size: 1.5rem;
  font-weight: bold;
  margin-bottom: var(--spacing-md);
}

.commission-step h3 {
  margin-bottom: var(--spacing-sm);
}

.commission-step p {
  margin-bottom: 0;
  font-size: 0.95rem;
  color: var(--color-text-light);
}

.commission-pricing-section {
  background-color: var(--color-accent-light);
}

.section-subtitle {
  text-align: center;
  color: var(--color-text-light);
  font-size: 1.05rem;
  margin-bottom: var(--spacing-xl);
}

.pricing-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  margin-bottom: var(--spacing-xl);
}

.pricing-card {
  background-color: var(--color-white);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  padding: var(--spacing-lg);
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
  transform: translateY(-4px);
}

.pricing-card-featured {
  border-color: var(--color-primary-dark);
  box-shadow: 0 4px 12px rgba(45, 90, 61, 0.15);
  transform: scale(1.02);
}

.featured-badge {
  position: absolute;
  top: -12px;
  right: var(--spacing-md);
  background-color: var(--color-primary-dark);
  color: var(--color-white);
  padding: 0.35rem 0.75rem;
  border-radius: 20px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
}

.pricing-card h3 {
  margin-bottom: var(--spacing-sm);
}

.price {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-md);
}

.pricing-features {
  list-style: none;
  margin-bottom: var(--spacing-md);
}

.pricing-features li {
  padding: var(--spacing-xs) 0;
  padding-left: 1.5rem;
  position: relative;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.pricing-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-primary-dark);
  font-weight: bold;
}

.pricing-note {
  text-align: center;
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.faq-list {
  display: grid;
  gap: var(--spacing-md);
}

.faq-item {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
}

.faq-item summary {
  padding: var(--spacing-md);
  cursor: pointer;
  font-weight: 600;
  color: var(--color-primary-dark);
  background-color: var(--color-accent-light);
  transition: var(--transition);
  user-select: none;
}

.faq-item summary:hover {
  background-color: #f0d9bf;
}

.faq-item summary:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
}

.faq-item[open] summary {
  background-color: #f0d9bf;
}

.faq-item p {
  padding: var(--spacing-md);
  background-color: var(--color-white);
  color: var(--color-text-light);
  margin-bottom: 0;
}

.commission-form-section {
  background-color: var(--color-white);
  border-top: 1px solid var(--color-border);
}

.commission-form {
  max-width: 600px;
  margin: 0 auto;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

@media (max-width: 600px) {
  .commission-steps {
    grid-template-columns: 1fr;
  }

  .pricing-grid {
    grid-template-columns: 1fr;
  }

  .pricing-card-featured {
    transform: scale(1);
  }

  .step-number {
    width: 2.5rem;
    height: 2.5rem;
    font-size: 1.25rem;
  }

  .faq-item summary {
    padding: var(--spacing-sm) var(--spacing-md);
  }

  .faq-item p {
    padding: var(--spacing-sm) var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .commission-steps {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  }

  .pricing-grid {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  }
}

.contact-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.contact-hero h1 {
  font-size: 2.5rem;
  margin-bottom: var(--spacing-md);
}

.contact-hero p {
  font-size: 1.125rem;
  color: var(--color-text-light);
  max-width: 600px;
}

.contact-content {
  padding: var(--spacing-xl) 0;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.contact-form-section {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
}

.contact-form-section h2 {
  margin-top: 0;
  font-size: 1.75rem;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.form-group label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

.form-group input,
.form-group textarea {
  width: 100%;
  padding: 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  transition: var(--transition);
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(45, 90, 61, 0.1);
