  margin-bottom: 0;
}

.commission-form-section {
  background-color: var(--color-white);
  border-top: 1px solid var(--color-border);
}

.commission-form {
  max-width: 600px;
  margin: 0 auto;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

@media (max-width: 600px) {
  .commission-steps {
    grid-template-columns: 1fr;
  }

  .pricing-grid {
    grid-template-columns: 1fr;
  }

  .pricing-card-featured {
    transform: scale(1);
  }

  .step-number {
    width: 2.5rem;
    height: 2.5rem;
    font-size: 1.25rem;
  }

  .faq-item summary {
    padding: var(--spacing-sm) var(--spacing-md);
  }

  .faq-item p {
    padding: var(--spacing-sm) var(--spacing-md);
  }
}

@media (min-width: 601px) {
  .commission-steps {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  }

  .pricing-grid {
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  }
}

.contact-hero {
  background-color: var(--color-accent-light);
  padding: var(--spacing-xl) 0;
}

.contact-hero h1 {
  font-size: 2.5rem;
  margin-bottom: var(--spacing-md);
}

.contact-hero p {
  font-size: 1.125rem;
  color: var(--color-text-light);
  max-width: 600px;
}

.contact-content {
  padding: var(--spacing-xl) 0;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xl);
  align-items: start;
}

.contact-form-section {
  background-color: var(--color-white);
  padding: var(--spacing-lg);
  border: 1px solid var(--color-border);
  border-radius: 8px;
}

.contact-form-section h2 {
  margin-top: 0;
  font-size: 1.75rem;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

.form-group label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-primary-dark);
}

.form-group input,
.form-group textarea {
  width: 100%;
  padding: 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  transition: var(--transition);
}

.form-group input:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(45, 90, 61, 0.1);
}

.form-group textarea {
  resize: vertical;
  min-height: 140px;
}

.contact-form button {
  width: 100%;
  margin-top: var(--spacing-md);
}

.contact-info {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-lg);
  border-radius: 8px;
}

.contact-info h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
  font-size: 1.75rem;
}

.contact-info h3 {
  color: var(--color-accent-on-dark);
  font-size: 1.25rem;
  margin-top: var(--spacing-md);
}

.contact-info h3:first-of-type {
  margin-top: 0;
}

.info-block {
  margin-bottom: var(--spacing-lg);
}

.info-block:last-child {
  margin-bottom: 0;
}

.contact-info p {
  margin-bottom: var(--spacing-sm);
  color: var(--color-accent-on-dark);
}

.contact-info a {
  color: var(--color-accent-on-dark);
  text-decoration: underline;
  transition: var(--transition);
}

.contact-info a:hover {
  color: var(--color-white);
}

.contact-info a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.info-note {
  font-size: 0.95rem;
  color: rgba(245, 217, 184, 0.85);
  margin-top: var(--spacing-xs);
}

@media (max-width: 600px) {
  .contact-hero {
    padding: var(--spacing-lg) 0;
  }

  .contact-hero h1 {
    font-size: 1.75rem;
  }

  .contact-hero p {
    font-size: 1rem;
  }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .contact-form-section {
    padding: var(--spacing-lg);
  }

  .contact-form-section h2,
  .contact-info h2 {
    font-size: 1.5rem;
  }

  .contact-info h3 {
    font-size: 1.125rem;
  }

  .form-group input,
  .form-group textarea {
    min-height: 44px;
  }

  .form-group textarea {
    min-height: 120px;
  }

  .contact-form button {
    min-height: 44px;
  }
}

@media (min-width: 601px) {
  .contact-hero {
    padding: var(--spacing-xl) 0;
  }
}
